// A: Numero di buchi
A := int(1,10);   // A e' DISCRETA: lo slider scatta all'intero al rilascio
float numHoles = max(floor(A + 0.5), 1.0); 

// Offset per mantenere la catena centrata
float offset_u = (numHoles - 1.0) / 2.0;

// Inizializzazione della distanza sicura
float d_final = 10000.0; 

// La variabile tempo per l'animazione (assicurati che il Play sia attivo)
float time_anim = ubuf.u_time; 

for(int k = int(0.0); k < int(20.0); k++) {
    float fk = float(k);

    if(fk < numHoles) { 
        float cx = (fk - offset_u) * max(D, 0.1);
        vec3 p_ring = vec3(p.x - cx, p.y, p.z);

        // --- DEFORMAZIONE CONTINUA ---
        // 'F' agisce da moltiplicatore del tempo:
        // F = 0.0 -> Animazione ferma, raggio dei buchi fisso e costante
        // F > 0.0 -> Animazione in avanti (velocità proporzionale a F)
        // F < 0.0 -> Animazione all'indietro
        float current_B = B * (0.5 + 0.5 * cos(F * time_anim - fk * 1.0));

        float d_ring = length(vec2(length(p_ring.xy) - current_B, p_ring.z)) - C;

        if(k == int(0.0)) {
            d_final = d_ring; 
        } else {
            d_final = -smax(-d_final, -d_ring, max(E, 0.01));
        }
    }
}

return d_final;

