// Velocità e posizione della linea di scansione
float scanSpeed = ubuf.u_time * 3.0;
float scanline = sin(pModel.y * 40.0 - scanSpeed);

// Rende la linea netta e luminosa
scanline = smoothstep(0.8, 1.0, scanline);

// Base = u_col2, bagliore della scansione = u_col1 (colori del dock)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, scanline);
